                StudyObjective(
                    id: "s6_describe_the_impact_of_corporate_brandin_obj",
                    title: "Describe the impact of corporate branding and styling.",
                    topics: [
                        StudyTopic(id: "s6_describe_the_impact_of_corporate_brandin_1", number: 1, question: "Explaining how corporate brand guidelines (color palettes, typography, logo usage) translate into Salesforce customization decisions such as themes and Experience Cloud branding.", answer: "Corporate brand guidelines define the visual identity: primary/secondary colors, approved fonts, logo usage rules, and imagery style. In Salesforce, these translate to: Lightning Experience themes (custom colors and logo in Setup > Themes and Branding), Experience Cloud site branding (header/footer colors, fonts, background images in Experience Builder), and SLDS token overrides for custom components. The designer's job is to implement brand guidelines within Salesforce's declarative limits and escalate to a developer when customization exceeds those limits."),
                        StudyTopic(id: "s6_describe_the_impact_of_corporate_brandin_2", number: 2, question: "Describing how consistent branding across internal Salesforce org and external Experience Cloud site affects user trust and adoption.", answer: "When the internal Salesforce org and the external Experience Cloud site share the same visual language (logo, colors, typography), users perceive a unified and professional experience. Inconsistency (e.g., a blue internal org and a red-branded partner portal) creates cognitive dissonance and erodes trust, signaling that the systems are disconnected. For customers or partners using the Experience Cloud site, brand consistency reinforces that they are interacting with a legitimate, polished touchpoint of the organization."),
                        StudyTopic(id: "s6_describe_the_impact_of_corporate_brandin_3", number: 3, question: "Identifying the risk of violating brand standards when custom CSS overrides conflict with SLDS tokens in a Lightning Experience implementation.", answer: "SLDS uses design tokens (CSS custom properties) to control colors, spacing, and typography globally. When developers write custom CSS that hard-codes values (e.g., a specific hex color) instead of referencing SLDS tokens, those overrides can break or look inconsistent after a Salesforce release updates the underlying tokens. Additionally, hard-coded custom CSS may overwrite brand-approved token values, violating brand standards. Best practice: always use SLDS tokens in custom components to maintain brand consistency and upgrade safety.")
                    ]
                )
            ]
        ),

        // Section 7: Describe key design principles and tools that define an acce (12 topics)
        StudySection(
            id: "s7_describe_key_design_principles_and_tools",
            title: "Describe key design principles and tools that define an accessible and engaging experience.",
            color: Color(red: 0.40, green: 0.60, blue: 0.30),
            lightColor: Color(red: 0.92, green: 0.96, blue: 0.90),
            icon: "leaf.fill",
            objectives: [
                StudyObjective(
                    id: "s7_describe_key_design_principles_and_tools_obj",
                    title: "Describe key design principles and tools that define an accessible and engaging experience.",
                    topics: [
                        StudyTopic(id: "s7_describe_key_design_principles_and_tools_1", number: 1, question: "The four POUR accessibility principles (Perceivable, Operable, Understandable, Robust) and what each principle addresses.", answer: "Perceivable: users must be able to perceive all UI information (e.g., images need alt text, videos need captions, color is not the only means of conveying information). Operable: users must be able to operate all UI controls (e.g., full keyboard navigation, no keyboard traps, sufficient time to complete actions). Understandable: UI and content must be comprehensible (e.g., clear error messages, consistent navigation, readable language). Robust: content must be interpretable by assistive technologies like screen readers (e.g., proper semantic HTML and ARIA roles). POUR is the foundation of WCAG."),
                        StudyTopic(id: "s7_describe_key_design_principles_and_tools_2", number: 2, question: "Applying WCAG 2.1 Level AA success criteria to identify accessibility failures in a described UI layout (e.g., insufficient color contrast, missing alt text, keyboard trap).", answer: "WCAG 2.1 Level AA is the standard required for most enterprise and government software. Common Level AA failures: insufficient color contrast (must meet 4.5:1 for normal text), missing alt text on informational images (violates Perceivable), keyboard trap (user cannot navigate away from a modal using keyboard only, violates Operable), no visible focus indicator for keyboard users (Operable), form fields without associated labels (Understandable). On the exam, identify which WCAG criterion is violated and which POUR principle it maps to."),
                        StudyTopic(id: "s7_describe_key_design_principles_and_tools_3", number: 3, question: "Applying WCAG minimum contrast ratio requirements (4.5:1 for normal text, 3:1 for large text) to evaluate whether a proposed color scheme passes accessibility standards.", answer: "WCAG 2.1 AA requires: 4.5:1 contrast ratio for normal text (under 18pt or 14pt bold) against its background, and 3:1 for large text (18pt or 14pt bold and above). The same 3:1 ratio applies to UI components and graphical objects (e.g., form field borders, icons). Tools like WebAIM Contrast Checker or browser DevTools can calculate ratios. On the exam, if a scenario presents a light gray text on white, recognize that it likely fails 4.5:1, making it a Perceivable WCAG violation."),
                        StudyTopic(id: "s7_describe_key_design_principles_and_tools_4", number: 4, question: "Mapping a given UI accessibility deficiency to the correct POUR principle (Perceivable, Operable, Understandable, Robust).", answer: "Perceivable violations: missing alt text, insufficient contrast, no captions on video, information conveyed by color alone. Operable violations: no keyboard access, keyboard trap, auto-playing content with no pause control, insufficient time limits. Understandable violations: unclear error messages, inconsistent navigation, jargon-heavy labels, form that changes context unexpectedly on input. Robust violations: custom components without ARIA roles, non-semantic HTML that screen readers cannot interpret. Memorize the mapping: what you can sense = Perceivable; what you can control = Operable; what you can comprehend = Understandable; what technology can parse = Robust."),
                        StudyTopic(id: "s7_describe_key_design_principles_and_tools_5", number: 5, question: "Identifying Gestalt principles (proximity, similarity, continuity, closure) as they apply to Salesforce page layout decisions.", answer: "Gestalt principles describe how humans perceive visual groupings. Proximity: elements placed close together are perceived as related (group related fields in the same section). Similarity: elements with the same color, shape, or size appear related (use consistent button styles for related actions). Continuity: the eye follows lines and curves (align fields in columns to create visual flow). Closure: the mind completes incomplete shapes (users infer content behind a 'See more' link). In Salesforce, these principles guide field grouping, tab structure, and component arrangement on Lightning record pages."),
                        StudyTopic(id: "s7_describe_key_design_principles_and_tools_6", number: 6, question: "Applying the concept of cognitive load theory to evaluate whether a proposed Salesforce page layout introduces unnecessary friction.", answer: "Cognitive load is the mental effort required to use an interface. Three types: intrinsic (complexity of the task itself), extraneous (complexity added by poor design), and germane (effort that builds useful understanding). UX designers aim to reduce extraneous load. In Salesforce, a page with 50 visible fields, unlabeled sections, and inconsistent action placement creates high extraneous cognitive load. Solutions include Dynamic Forms to show only relevant fields, clear section headings, and consistent action placement, all of which reduce mental effort without reducing task capability."),
                        StudyTopic(id: "s7_describe_key_design_principles_and_tools_7", number: 7, question: "Distinguishing when to use progressive disclosure to reduce cognitive load vs. when showing all information upfront is preferable given user role and task frequency.", answer: "Progressive disclosure hides secondary information behind interactions (e.g., 'Show more fields', accordion sections, tabs). It reduces initial cognitive load and is appropriate when: most users rarely need the hidden information, or the user is a novice who would be overwhelmed by all options at once. Show all information upfront when: users are power users who need instant access to all fields (hiding data forces extra clicks), or task frequency is very high (a service agent handling 50 cases/day cannot afford extra clicks to reveal fields on every record)."),
                        StudyTopic(id: "s7_describe_key_design_principles_and_tools_8", number: 8, question: "Selecting the correct visual hierarchy technique (size, weight, color, whitespace) to guide user attention on a record detail page.", answer: "Visual hierarchy directs the user's eye to the most important information first. Techniques: Size (larger text = higher priority; use for record name or key status). Weight (bold text stands out; use for field labels or critical values). Color (use sparingly; a single accent color draws attention, e.g., a red badge for overdue cases). Whitespace (space around an element increases its perceived importance and reduces visual noise). On a Salesforce record page, apply these by placing high-priority fields in the highlights panel (compact layout) and using clear section headings."),
                        StudyTopic(id: "s7_describe_key_design_principles_and_tools_9", number: 9, question: "Applying affordance and feedback principles (visible clickability cues, loading states, success confirmations) to ensure users understand system status after taking an action in Salesforce.", answer: "Affordance means a design element communicates how it is used: a button looks clickable, a text field looks editable. Feedback is the system's response to user actions. Nielsen Heuristic #1 is 'Visibility of system status.' In Salesforce: use SLDS button styles so actions look interactive; show a spinner or skeleton screen while data loads; display a toast notification upon successful save; show an inline error immediately when validation fails. Without clear feedback, users re-submit forms, click buttons multiple times, or abandon tasks believing the system is broken."),
                        StudyTopic(id: "s7_describe_key_design_principles_and_tools_10", number: 10, question: "Evaluating information architecture (IA) decisions — navigation labeling, grouping, and hierarchy — to ensure users can predict where to find functionality without prior training.", answer: "Good IA means users can predict where things are based on their mental model, not the system's data model. Evaluate IA by asking: Are navigation labels in the user's language (not internal jargon)? Are related functions grouped together? Is the hierarchy shallow enough that users can reach any item in 2-3 clicks? In Salesforce, IA decisions include which objects appear in the app navigation bar, how page sections are titled and ordered, and whether global search surfaces the right object types. Card sorting and tree testing are the primary tools for validating these decisions."),
                        StudyTopic(id: "s7_describe_key_design_principles_and_tools_11", number: 11, question: "Writing actionable, non-technical error messages and microcopy for Salesforce forms.", answer: "Effective error messages tell the user what went wrong and what to do next, in plain language. Bad: 'Error code 400 - Invalid input.' Good: 'Please enter a valid email address (example@domain.com).' Microcopy includes button labels, placeholder text, help text, and confirmation messages. It should be clear, concise, and action-oriented. In Salesforce, field-level help text should explain the expected format or business rule, not restate the field label. Button labels should describe the action ('Save and Close') not just a generic verb ('Submit')."),
                        StudyTopic(id: "s7_describe_key_design_principles_and_tools_12", number: 12, question: "Distinguishing inline validation errors from page-level error summaries in Salesforce forms and when each presentation is appropriate.", answer: "Inline validation shows an error message directly beneath the field that has the problem, immediately after the user leaves the field (on blur) or after submission. It is best for real-time feedback on individual fields. Page-level error summaries appear at the top of the form after submission, listing all validation failures. They are useful for screen reader users (who may not encounter inline errors) and when multiple fields have errors. Best practice: use both together, inline for contextual feedback and a page-level summary for accessibility and a complete overview.")
                    ]
                )
            ]
        ),

        // Section 8: Describe mobile UX design fundamentals. (5 topics)
        StudySection(
            id: "s8_describe_mobile_ux_design_fundamentals",
            title: "Describe mobile UX design fundamentals.",
            color: Color(red: 0.50, green: 0.30, blue: 0.60),
            lightColor: Color(red: 0.94, green: 0.90, blue: 0.96),
            icon: "cpu.fill",
            objectives: [
                StudyObjective(
                    id: "s8_describe_mobile_ux_design_fundamentals_obj",
                    title: "Describe mobile UX design fundamentals.",
                    topics: [
                        StudyTopic(id: "s8_describe_mobile_ux_design_fundamentals_1", number: 1, question: "Identifying mobile UX constraints (small screen real estate, touch targets, thumb zones) that should influence Salesforce page layout decisions for the Salesforce mobile app.", answer: "Small screen real estate means fewer fields, sections, and actions should be visible at once. Touch targets must be at least 44x44 points (Apple HIG) or 48x48dp (Material Design) to be accurately tappable. Thumb zones describe areas of a phone screen that are easy vs. hard to reach with one thumb: the bottom-center is easy; the top corners are hard. Place primary actions in the bottom-center thumb zone. In Salesforce mobile, these constraints drive compact layout design (limit highlighted fields to the most critical) and action placement (most-used quick actions first)."),
                        StudyTopic(id: "s8_describe_mobile_ux_design_fundamentals_2", number: 2, question: "Distinguishing between responsive design (layout adapts fluidly to screen size) and adaptive design (distinct layouts served per breakpoint) and identifying which approach is used in Lightning Experience and Experience Cloud.", answer: "Responsive design uses fluid grids and CSS media queries so the same HTML reflows based on viewport width. Adaptive design serves a distinctly different layout for defined breakpoints (e.g., a completely different page for mobile vs. desktop). Lightning Experience uses a responsive design approach: the Lightning page layout reflows into a single-column layout on smaller screens. Experience Cloud also uses responsive design in templates. Salesforce mobile app serves a native app experience that uses compact layouts and a separate mobile navigation, which is closer to adaptive behavior."),
                        StudyTopic(id: "s8_describe_mobile_ux_design_fundamentals_3", number: 3, question: "Applying mobile-first design principles to prioritize which fields and actions appear on a Salesforce mobile compact layout.", answer: "Mobile-first design means designing for the smallest screen first, then progressively enhancing for larger screens. For a Salesforce compact layout, this means selecting only the 4-7 most critical fields a mobile user needs to see at a glance on the highlights panel (e.g., name, status, phone number for a Contact). For quick actions, list only the actions a field user performs most frequently (e.g., Log a Call, Send Email). Everything else can be accessed by scrolling or tapping into the full record."),
                        StudyTopic(id: "s8_describe_mobile_ux_design_fundamentals_4", number: 4, question: "Determining when a mobile-specific compact layout is required vs. when the standard desktop layout is acceptable given a described user scenario.", answer: "A mobile-specific compact layout is required when: the user persona primarily works on a mobile device (field service tech, sales rep on the road), the task requires quick data entry or lookup in the field, or the desktop layout contains so many fields that it is unusable on a small screen. The standard desktop layout is acceptable when: mobile usage is rare or incidental for that persona, the task is complex enough to require a full desktop anyway, or the desktop layout has already been designed with minimal field density."),
                        StudyTopic(id: "s8_describe_mobile_ux_design_fundamentals_5", number: 5, question: "Identifying the UX impact of offline capability limitations in the Salesforce mobile app when designing for field service or remote worker personas.", answer: "The Salesforce mobile app has limited offline functionality. Standard records (like Contacts) are not available offline by default. Salesforce Field Service has dedicated offline capabilities. For field service or remote worker personas who work in areas with poor connectivity, this means: design workflows that can be completed offline and synced later, avoid real-time data lookups in critical paths, and communicate clearly to users what data is available offline vs. not. Failing to account for offline limitations in the design leads to task failure at the worst possible moment.")
                    ]
                )
            ]
        ),

        // Section 9: Given a scenario, determine how to incorporate human-centere (10 topics)
        StudySection(
            id: "s9_given_a_scenario_determine_how_to_incorp",
            title: "Given a scenario, determine how to incorporate human-centered design into a customer solution.",
            color: Color(red: 0.60, green: 0.50, blue: 0.20),
            lightColor: Color(red: 0.98, green: 0.96, blue: 0.88),
            icon: "lightbulb.fill",
            objectives: [
                StudyObjective(
                    id: "s9_given_a_scenario_determine_how_to_incorp_obj",
                    title: "Given a scenario, determine how to incorporate human-centered design into a customer solution.",
                    topics: [
                        StudyTopic(id: "s9_given_a_scenario_determine_how_to_incorp_1", number: 1, question: "Distinguishing between divergent thinking (ideation, brainstorming) and convergent thinking (prioritization, decision-making) and when to apply each in a design process.", answer: "Divergent thinking expands the possibility space: generate as many ideas as possible without judgment. Techniques include brainstorming, Crazy 8s, mind mapping, and How Might We prompts. Convergent thinking narrows options to the best solution: evaluate, prioritize, and decide. Techniques include dot voting, impact/effort matrices, and feasibility reviews. In a design process, diverge before you converge: first generate broad options (ideation phase), then select the most promising ones (decision phase). Skipping divergence leads to first-idea solutions; skipping convergence leads to endless ideation without progress."),
                        StudyTopic(id: "s9_given_a_scenario_determine_how_to_incorp_2", number: 2, question: "Determining how to build empathy with users (shadowing, contextual inquiry, think-aloud protocols) when direct access to end users is restricted by the client.", answer: "Shadowing: observe users in their work environment without interrupting; reveals real behaviors. Contextual inquiry: combined observation and interview conducted in the user's environment; reveals context and rationale. Think-aloud protocol: ask users to verbalize their thoughts while completing a task; reveals mental models and decision points. When direct access is restricted, alternatives include: interviewing managers or team leads who observe users daily, reviewing support tickets and call recordings, analyzing behavioral analytics, or running an unmoderated remote study. Any form of empathy-building is better than designing on assumptions alone."),
                        StudyTopic(id: "s9_given_a_scenario_determine_how_to_incorp_3", number: 3, question: "Identifying the correct phase of the Double Diamond model (Discover, Define, Develop, Deliver) to apply given a described project situation.", answer: "Discover: explore the problem space through research; divergent. Define: synthesize research into a clear problem statement; convergent. Develop: ideate and prototype potential solutions; divergent. Deliver: test, refine, and ship the best solution; convergent. The model has two diamonds because it diverges (explores broadly) then converges (focuses) twice: once to define the right problem, and once to build the right solution. On the exam: if the team does not yet know what problem to solve, they are in Discover. If they have a defined problem and are generating ideas, they are in Develop."),
                        StudyTopic(id: "s9_given_a_scenario_determine_how_to_incorp_4", number: 4, question: "Recognizing the role of rapid iteration and feedback loops in human-centered design and when a team should cycle back to earlier phases instead of moving forward.", answer: "Human-centered design is iterative: teams regularly test ideas with users and refine based on findings rather than building in a straight line. A team should cycle back when: usability testing reveals a fundamental misunderstanding of the user's need (cycle back to Define), when a prototype fails to address the problem statement (cycle back to Develop), or when new stakeholder information invalidates research assumptions (cycle back to Discover). The signal to cycle back is a finding that challenges the foundational assumption of the current phase."),
                        StudyTopic(id: "s9_given_a_scenario_determine_how_to_incorp_5", number: 5, question: "Applying jobs-to-be-done (JTBD) framing to reframe a stakeholder's feature request into a user-centered problem statement.", answer: "Jobs-to-be-done focuses on what the user is trying to accomplish (the 'job'), not the feature they are requesting. Format: 'When [situation], I want to [motivation/goal], so I can [expected outcome].' Stakeholder request: 'Add a notes field to the Opportunity.' JTBD reframe: 'When I finish a customer call, I want to quickly capture key discussion points, so I can reference them before the next meeting without opening a separate tool.' The JTBD frame reveals the underlying need, opening the solution space beyond the literal feature request."),
                        StudyTopic(id: "s9_given_a_scenario_determine_how_to_incorp_6", number: 6, question: "Evaluating whether a proposed Salesforce solution adequately addresses the user's mental model vs. the system's data model.", answer: "A user's mental model is how they conceptually understand their work (e.g., a sales rep thinks 'I'm managing a deal,' not 'I'm editing an Opportunity record with a child Contact and related Activities'). A system's data model is how the software structures the data (objects, relationships, fields). When the Salesforce solution forces users to think in terms of the system's data model (navigate to the Account, then find the Contact, then find the Opportunity), it creates friction. A good UX bridges the gap by presenting data in a way that maps to the user's mental model, such as surfacing related records on a single page."),
                        StudyTopic(id: "s9_given_a_scenario_determine_how_to_incorp_7", number: 7, question: "Applying an assumption map (known vs. unknown, high vs. low risk) to prioritize which design assumptions must be validated through research before committing to a solution direction.", answer: "An assumption map plots design assumptions on two axes: how well-known the assumption is (known vs. unknown) and how risky it is if wrong (high vs. low risk). Assumptions that are unknown AND high-risk must be validated first before committing resources. Assumptions that are known AND low-risk can be acted on without additional research. This helps teams avoid the trap of researching everything (inefficient) or nothing (risky). In a Salesforce project, a high-risk assumption might be 'Users will adopt the mobile app for field logging'; unknown and high-risk means you need to validate it before investing in mobile configuration."),
                        StudyTopic(id: "s9_given_a_scenario_determine_how_to_incorp_8", number: 8, question: "Selecting the appropriate co-design or participatory design technique to involve users when the team has limited research budget and compressed timeline.", answer: "Co-design involves users as active participants in the design process, not just subjects. Low-budget, time-constrained techniques include: design studio workshops (users and designers sketch solutions together in a structured session), participatory prototyping (users annotate or modify existing wireframes), and card sorting (users self-organize content categories). These methods generate user input quickly and build user buy-in simultaneously. They are most effective when access to even a small group of representative users is possible."),
                        StudyTopic(id: "s9_given_a_scenario_determine_how_to_incorp_9", number: 9, question: "The five phases of the Design Sprint methodology: Map, Sketch, Decide, Prototype, and Test.", answer: "Map: the team maps the problem space and defines the sprint's target challenge (Day 1). Sketch: each team member independently sketches solutions (Day 2). Decide: the team votes on the best solution to prototype (Day 3). Prototype: a realistic but fake prototype is built quickly (Day 4). Test: the prototype is tested with 5 real users (Day 5). The Design Sprint was created by Google Ventures to compress weeks of design work into 5 days. The key output is validated learning about whether a proposed solution addresses a user need."),
                        StudyTopic(id: "s9_given_a_scenario_determine_how_to_incorp_10", number: 10, question: "When the Design Sprint methodology is an appropriate compressed alternative to a full discovery and design process.", answer: "A Design Sprint is appropriate when: the team is stuck on a critical decision and needs fast validated learning, there is a high-stakes problem that warrants rapid prototyping and testing before committing to development, or the project timeline does not allow for a full multi-week discovery. It is NOT appropriate when: the problem space is entirely unknown (a Sprint assumes enough context to sketch solutions on Day 2), or when user recruitment is impossible (Day 5 requires 5 real users). Think of a Sprint as a time-boxed alternative when you have some problem clarity but need fast validation.")
                    ]
                )
            ]
        ),

        // Section 10: Explain the importance of inclusive design. (6 topics)
        StudySection(
            id: "s10_explain_the_importance_of_inclusive_desi",
            title: "Explain the importance of inclusive design.",
            color: Color(red: 0.35, green: 0.45, blue: 0.65),
            lightColor: Color(red: 0.90, green: 0.92, blue: 0.96),
            icon: "building.2.fill",
            objectives: [
                StudyObjective(
                    id: "s10_explain_the_importance_of_inclusive_desi_obj",
                    title: "Explain the importance of inclusive design.",
                    topics: [
                        StudyTopic(id: "s10_explain_the_importance_of_inclusive_desi_1", number: 1, question: "Differentiating inclusive design from accessibility: understanding that inclusive design is a methodology that benefits all users, not just those with disabilities.", answer: "Accessibility is a set of technical standards (WCAG) ensuring that users with disabilities can use a product. It is compliance-focused and specific. Inclusive design is a broader methodology that considers the full spectrum of human diversity (ability, age, gender, language, context) during the design process. It goes beyond compliance: it actively involves diverse users in research and design to create solutions that work better for everyone. All accessible products involve some inclusive design thinking, but inclusive design produces outputs that benefit far more than just users with disabilities."),
                        StudyTopic(id: "s10_explain_the_importance_of_inclusive_desi_2", number: 2, question: "The three Microsoft Inclusive Design principles: Recognize Exclusion, Solve for One Extend to Many, and Learn from Diversity.", answer: "Recognize Exclusion: acknowledge that design decisions can inadvertently exclude people, and identify who is being excluded by current assumptions. Solve for One, Extend to Many: design solutions for the most constrained user (e.g., someone with a motor impairment) and the result will benefit everyone (e.g., voice input helps the motor-impaired user AND a driver who cannot use their hands). Learn from Diversity: include people with diverse abilities and contexts in the research process, because their unique perspectives reveal design failures invisible to the majority audience."),
                        StudyTopic(id: "s10_explain_the_importance_of_inclusive_desi_3", number: 3, question: "Explaining the concept of situational disability (temporary or environmental impairment such as a broken arm, bright sunlight, or noisy environment) and why inclusive design addresses a broader audience than traditional accessibility compliance.", answer: "Situational disability is when a person temporarily experiences constraints similar to a permanent disability: a broken arm mimics a motor impairment; bright outdoor sunlight mimics a visual impairment; a loud environment mimics a hearing impairment; holding a baby mimics a one-handed user. This concept demonstrates that disability is not binary (disabled/not disabled) but a spectrum that affects everyone at some point. Designing for permanent disabilities produces solutions (voice control, high contrast, captions) that benefit all users in situational constraints, dramatically expanding the audience for inclusive design solutions."),
                        StudyTopic(id: "s10_explain_the_importance_of_inclusive_desi_4", number: 4, question: "Identifying how designing for edge cases (users with motor, vision, cognitive, or situational impairments) creates solutions that improve usability for the entire user population.", answer: "Classic examples: closed captions were designed for Deaf users but are widely used in noisy environments. Curb cuts were designed for wheelchair users but benefit cyclists, parents with strollers, and delivery workers. In Salesforce, designing for cognitive impairment (simplifying page layouts, using plain language, adding in-app guidance) produces an experience that is easier for all users, including power users during high-stress situations. Edge-case design forces clarity and simplicity that benefits everyone."),
                        StudyTopic(id: "s10_explain_the_importance_of_inclusive_desi_5", number: 5, question: "Applying Microsoft Inclusive Design principles to a Salesforce UX decision.", answer: "Example application: A field service team has technicians with varying digital literacy levels and sometimes work with one gloved hand (situational disability). Applying 'Solve for One, Extend to Many': design the mobile Salesforce layout for one-handed use with large touch targets and minimal typing, which also benefits all technicians regardless of glove use. Applying 'Recognize Exclusion': identify that the current flow requires reading small print on a bright screen, excluding techs working outdoors. Solution: increase font size and contrast, benefiting all users. Applying 'Learn from Diversity': include a low-literacy technician in usability testing to surface terminology and navigation problems invisible to the design team."),
                        StudyTopic(id: "s10_explain_the_importance_of_inclusive_desi_6", number: 6, question: "Identifying how bias in persona creation or user research can lead to exclusionary design decisions in a Salesforce solution.", answer: "If research only includes the most digitally literate, most available, or most vocal users, the resulting personas will not represent the full user population. Bias examples: recruiting only office-based employees excludes field workers; creating a persona based on the 'ideal user' rather than the actual user population; defaulting to a male name and photo on a persona for a role that is predominantly female. Exclusionary personas lead to design decisions that optimize for the represented group and inadvertently add friction for the excluded majority. Mitigate bias by actively recruiting from diverse segments and auditing persona assumptions.")
                    ]
                )
            ]
        ),

        // Section 11: Given a scenario, describe how core Salesforce objects funct (6 topics)
        StudySection(
            id: "s11_given_a_scenario_describe_how_core_sales",
            title: "Given a scenario, describe how core Salesforce objects function, how that can affect the user experience, and when to use and customize them.",
            color: Color(red: 0.30, green: 0.50, blue: 0.80),
            lightColor: Color(red: 0.90, green: 0.94, blue: 1.00),
            icon: "doc.text.fill",
            objectives: [
                StudyObjective(
                    id: "s11_given_a_scenario_describe_how_core_sales_obj",
                    title: "Given a scenario, describe how core Salesforce objects function, how that can affect the user experience, and when to use and customize them.",
                    topics: [
                        StudyTopic(id: "s11_given_a_scenario_describe_how_core_sales_1", number: 1, question: "Selecting between standard objects (Account, Contact, Opportunity, Case) and custom objects based on the user's workflow and data relationship requirements.", answer: "Standard objects (Account, Contact, Opportunity, Case, Lead, etc.) come pre-built with Salesforce functionality, reports, dashboards, and process automation support. Use them whenever the standard object's purpose aligns with the business concept. Custom objects are created when no standard object fits, such as a 'Job Application' or 'Project Milestone' object. From a UX perspective, standard objects carry existing user familiarity (if the org has previously used them), built-in related lists, and Salesforce-native features. Overusing custom objects can fragment the user experience and increase navigation complexity."),
                        StudyTopic(id: "s11_given_a_scenario_describe_how_core_sales_2", number: 2, question: "UX impact of lookup vs. master-detail relationships on related list display and record access.", answer: "A lookup relationship is a loose link between two objects. The child record can exist independently; the lookup field can be empty. Related lists on the parent appear automatically. From a UX standpoint, lookups allow flexibility but require users to manually manage the relationship. A master-detail relationship tightly links the child to the parent; the child cannot exist without the parent. The child record is always associated and accessible from the parent's related list. UX impact: master-detail makes parent-child navigation predictable and automatic; lookups require users to ensure they correctly populate the relationship field."),
                        StudyTopic(id: "s11_given_a_scenario_describe_how_core_sales_3", number: 3, question: "UX implications of master-detail relationships: rollup summaries and cascading deletes.", answer: "Rollup summary fields calculate aggregate values (SUM, COUNT, MIN, MAX) from child records and display them on the master record, eliminating the need for users to manually calculate or navigate to a report. From a UX standpoint, this surfaces key metrics (e.g., total line item value on an Order) directly on the master record. Cascading deletes mean that deleting the master record automatically deletes all child records, which is a serious data loss risk. UX designers must ensure users are clearly warned about this consequence before deleting a master record."),
                        StudyTopic(id: "s11_given_a_scenario_describe_how_core_sales_4", number: 4, question: "Identifying how junction objects model many-to-many relationships and what UX considerations arise when users need to work with junction object records.", answer: "A junction object connects two objects in a many-to-many relationship using two master-detail relationships. Example: a 'Campaign Member' junction object links Contacts to Campaigns. UX considerations: users often don't think in terms of junction objects; they think 'I want to add this Contact to this Campaign.' Expose the junction object interaction through a related list or quick action on one of the parent than forcing users to navigate directly to the junction object. The junction object record page itself is often irrelevant to the user and should be de-emphasized."),
                        StudyTopic(id: "s11_given_a_scenario_describe_how_core_sales_5", number: 5, question: "Distinguishing how Activities (Tasks and Events) behave on the activity timeline and how that affects the UX design of sales or service workflows.", answer: "Tasks are to-dos: they have a subject, due date, priority, and assigned user. Events are calendar items with start/end times. Both appear on the Activity Timeline on record pages (e.g., on an Opportunity or Contact). The timeline shows past interactions and upcoming activities in chronological order. UX design implication: the activity timeline is a powerful context tool for sales and service reps, showing call logs, emails, and meetings without leaving the record. Design should ensure reps log activities consistently (use quick actions and automation to reduce friction) so the timeline remains a reliable source of truth."),
                        StudyTopic(id: "s11_given_a_scenario_describe_how_core_sales_6", number: 6, question: "Evaluating when to rename standard objects and fields to match business terminology vs. when doing so introduces confusion with Salesforce documentation and help text.", answer: "Renaming standard objects (e.g., renaming 'Account' to 'Client' or 'Opportunity' to 'Deal') aligns the UI with the user's mental model and business language, which can increase adoption. However, it creates a mismatch with Salesforce's own Help & Training, Trailhead, and release notes, which use standard names. Admins and power users troubleshooting issues may be confused when searching Salesforce documentation. Best practice: rename for End Users who never interact with Salesforce documentation; retain standard names for Admin-facing interfaces and training materials that reference official Salesforce resources.")
                    ]
                )
            ]
        ),

        // Section 12: Given a scenario, describe declarative features that improve (12 topics)
        StudySection(
            id: "s12_given_a_scenario_describe_declarative_fe",
            title: "Given a scenario, describe declarative features that improve information presentation, hierarchy, and architecture in static experiences.",
            color: Color(red: 0.20, green: 0.60, blue: 0.50),
            lightColor: Color(red: 0.88, green: 0.96, blue: 0.94),
            icon: "checkmark.shield.fill",
            objectives: [
                StudyObjective(
                    id: "s12_given_a_scenario_describe_declarative_fe_obj",
                    title: "Given a scenario, describe declarative features that improve information presentation, hierarchy, and architecture in static experiences.",
                    topics: [
                        StudyTopic(id: "s12_given_a_scenario_describe_declarative_fe_1", number: 1, question: "Distinguishing between Record Home pages, App Home pages, and Home pages in Lightning App Builder and identifying which page type to customize for a given UX goal.", answer: "Home page: the default landing page when users log in or navigate to the Home tab; customize for dashboards, news, and key metrics relevant to all users or a persona. App Home page: the home page specific to a Lightning App; customize it to surface the most relevant content for that app's primary persona (e.g., a Service Console app home showing open case counts). Record Home page: the page layout for a specific object record (e.g., an Account or Opportunity record); customize it to optimize the field layout and components for that object's primary user task. Match the page type to where the user needs the customization."),
                        StudyTopic(id: "s12_given_a_scenario_describe_declarative_fe_2", number: 2, question: "Configuring Lightning page layouts using the Lightning App Builder to optimize field density, component placement, and tab structure for a specific user role.", answer: "The Lightning App Builder uses a drag-and-drop canvas to place standard and custom components on a record or home page. For field density: use the Details tab component (which references the page layout) and configure the page layout to include only role-relevant fields. For component placement: place high-priority components (Highlights Panel, Key Metrics) at the top; supporting components (Activity Timeline, Related Lists) below. Use tabs to separate major content areas (Details, Related, Activity) and reduce vertical scrolling. Assign different page variations to different user profiles or app contexts."),
                        StudyTopic(id: "s12_given_a_scenario_describe_declarative_fe_3", number: 3, question: "Choosing between Dynamic Forms and standard page layouts to control field visibility and reduce clutter on record detail pages.", answer: "Standard page layouts assign all fields to sections and apply that same layout to all record types or profiles (with some profile-based field visibility). Dynamic Forms replace the standard Details component with individually placed field components and field sections directly on the Lightning page. This allows field-level visibility rules (show this field only when Status = 'Active') and profile-based section visibility without separate record types. Dynamic Forms are the superior choice when field visibility needs to be conditional on data values. Use standard page layouts when simplicity and broad compatibility are priorities."),
                        StudyTopic(id: "s12_given_a_scenario_describe_declarative_fe_4", number: 4, question: "Using compact layouts to surface the most critical fields in record highlights panels, Kanban views, and mobile cards.", answer: "A compact layout defines the small set of fields (typically 4-7) that appear in the highlights panel at the top of a record page, in Kanban cards, in hover popups, and on mobile record cards. It answers: 'What does a user need to know at a glance before opening the full record?' For an Opportunity: Stage, Amount, Close Date, Account Name, and Owner. For a Case: Subject, Status, Priority, and Contact. Compact layouts are assigned to profiles, so different personas can see the fields most relevant to their role at a glance."),
                        StudyTopic(id: "s12_given_a_scenario_describe_declarative_fe_5", number: 5, question: "Applying List Views with filters and column selection to improve user efficiency in high-volume record management scenarios.", answer: "List Views allow users to filter records by criteria (e.g., 'My Open Opportunities' or 'Cases Opened This Week') and display selected columns relevant to the task. From a UX standpoint, a well-designed list view eliminates the need for a custom report for routine monitoring tasks. For high-volume users: create predefined list views for the most common filter combinations, select the columns they need to act without opening each record (e.g., show phone number on a Contacts list view so reps can call without clicking in), and enable the Kanban view toggle for pipeline management."),
                        StudyTopic(id: "s12_given_a_scenario_describe_declarative_fe_6", number: 6, question: "Configuring Kanban views and when they are preferable to list views for managing pipeline or process stages.", answer: "A Kanban view displays records as cards grouped by a picklist field (e.g., Stage, Status) in vertical columns. Users can drag and drop cards between columns to update the field. Kanban is preferable to a list view when: users need to visualize the distribution of records across stages (pipeline review), users frequently move records between stages (drag-and-drop is faster than opening a record and editing), or the team needs to identify bottlenecks (columns with too many cards). Use list views when: users need to see more data per record than a card can display, or when filtering and sorting by multiple fields is the primary task."),
                        StudyTopic(id: "s12_given_a_scenario_describe_declarative_fe_7", number: 7, question: "Comparing the UX implications of using tabs vs. accordion sections vs. collapsible panels in a Lightning record page to manage dense information.", answer: "Tabs: present distinct content areas side by side (e.g., Details, Related, Activity). Only one tab is visible at a time; users must switch to see other content. Best for logically separate content groups. Accordion sections: vertically stacked sections that expand/collapse. Multiple sections can be open simultaneously. Best for secondary information users may want to scan without full navigation. Collapsible panels: similar to accordions but often used for sidebar or supplementary content. Best for information relevant only to specific tasks. Tabs reduce vertical scrolling but hide content; accordions allow comparison of expanded sections; all three reduce initial cognitive load through progressive disclosure."),
                        StudyTopic(id: "s12_given_a_scenario_describe_declarative_fe_8", number: 8, question: "Deciding when to use related lists vs. related list quick links vs. related record components based on how frequently users need to navigate to child records.", answer: "Related lists show all child records of a related object in a table format (e.g., all Contacts on an Account). Use when users frequently work with multiple child records at once. Related list quick links show a count badge and a link to the full related list, surfacing the count without loading all records. Use for frequently referenced but rarely navigated relationships. Related record components display the detail fields of a single related record inline on the parent page. Use when users need to see or edit one specific related record (e.g., a primary Contact's details on an Opportunity) without navigating away."),
                        StudyTopic(id: "s12_given_a_scenario_describe_declarative_fe_9", number: 9, question: "Using Path (Sales Path / Service Path) to provide stage-based coaching and highlight key fields at each process stage.", answer: "Path is a visual pipeline indicator that shows the stages of a process (e.g., Opportunity stages or Case statuses) as a horizontal bar at the top of a record page. At each stage, Path can display key fields relevant to that stage (fields the user should complete before moving forward) and guidance text (coaching tips or process instructions). UX benefits: it maps the system's process to the user's mental model of 'where am I in this deal/case?', surfaces only the relevant fields for the current stage (reducing cognitive load), and provides in-context coaching without requiring separate documentation."),
                        StudyTopic(id: "s12_given_a_scenario_describe_declarative_fe_10", number: 10, question: "Configuring Dynamic Actions (show/hide buttons based on field values or user criteria) to reduce action bar clutter and surface only contextually relevant actions to the user.", answer: "Dynamic Actions allow admins to add filter conditions to buttons in the Lightning page's action bar (e.g., show 'Submit for Approval' only when Stage = 'Proposal' and Amount > 10,000). Without Dynamic Actions, all configured actions appear to all users at all times, creating an overwhelming action bar with irrelevant buttons. Dynamic Actions reduce this clutter so users only see actions that are currently valid and relevant to their context, applying the principle of progressive disclosure to the action bar."),
                        StudyTopic(id: "s12_given_a_scenario_describe_declarative_fe_11", number: 11, question: "Identifying the UX role of field-level help text vs. in-app guidance prompts in reducing user confusion without cluttering the interface.", answer: "Field-level help text is a question-mark icon next to a field that, when hovered, displays a tooltip explaining the field's purpose, expected format, or business rule. It is persistent, always available, and reduces support tickets for field interpretation. In-app guidance (Prompts and Walkthroughs) are contextual pop-ups or spotlight callouts triggered at specific moments (e.g., first login, feature release) to guide users through new functionality. Use field-level help text for ongoing, field-specific clarification. Use in-app guidance for one-time or event-driven onboarding and adoption scenarios."),
                        StudyTopic(id: "s12_given_a_scenario_describe_declarative_fe_12", number: 12, question: "Using Report and Dashboard components on Lightning pages to surface actionable analytics in context, reducing the need for users to navigate away from their primary workflow.", answer: "Report chart components and dashboard components can be embedded directly into Lightning App Home pages and Record Home pages. This means a sales manager can see a pipeline dashboard on the App Home page without navigating to the Reports tab. A service rep can see a case aging chart on the Case Home page. The UX benefit is reduced navigation (fewer clicks to get insight), and context-relevant analytics (the user sees data pertaining to their current workflow). The design consideration is not to overload a page with too many report components, which creates visual noise.")
                    ]
                )
            ]
        ),

        // Section 13: Given a scenario, describe declarative features that improve (12 topics)
        StudySection(
            id: "s13_given_a_scenario_describe_declarative_fe",
            title: "Given a scenario, describe declarative features that improve user efficiency over a series of steps.",
            color: Color(red: 0.55, green: 0.35, blue: 0.75),
            lightColor: Color(red: 0.94, green: 0.90, blue: 0.98),
            icon: "gearshape.2.fill",
            objectives: [
                StudyObjective(
                    id: "s13_given_a_scenario_describe_declarative_fe_obj",
                    title: "Given a scenario, describe declarative features that improve user efficiency over a series of steps.",
                    topics: [
                        StudyTopic(id: "s13_given_a_scenario_describe_declarative_fe_1", number: 1, question: "Distinguishing between global actions and object-specific actions and their respective use cases.", answer: "Global actions are available from the global action bar (the '+' icon in the header) regardless of which page or object the user is on. Use cases: create a new record, log a call, or send an email from anywhere in the org. Object-specific actions appear in the action bar on a specific object's record page. They can be pre-configured to interact with that object's data (e.g., a 'Create Related Case' action on a Contact that pre-fills the Contact's name). Use global actions for universal tasks; use object-specific actions for tasks that are contextually tied to a particular object's record."),
                        StudyTopic(id: "s13_given_a_scenario_describe_declarative_fe_2", number: 2, question: "Identifying when Quick Actions (object-specific or global) improve task efficiency by pre-populating fields and launching modal dialogs without full page navigation.", answer: "Quick Actions launch a modal dialog overlay on the current page, so the user completes a task (create, update, log) without navigating away. They can be pre-configured to auto-populate fields from the current record context (e.g., a 'New Task' quick action on an Opportunity that pre-fills the Opportunity Name and Account). This eliminates the manual lookup step. The UX benefit is task completion without losing the user's current context. Use Quick Actions for frequent, short tasks (log a call, update a stage, create a related record) that do not require a full-page form."),
                        StudyTopic(id: "s13_given_a_scenario_describe_declarative_fe_3", number: 3, question: "Which Quick Action types (Create, Update, Log a Call, Flow, Custom) are available in global vs. object-specific contexts and their UX implications.", answer: "Create: creates a new record; available globally and on objects. Update: updates fields on the current record; only available on object-specific action bars. Log a Call: specialized Create action for Activity records; available globally and on objects. Flow: launches a Screen Flow in a modal; available globally and on objects, enabling guided multi-step tasks within a quick action. Custom (Visualforce or LWC): launches a custom page in a modal; object-specific. UX implication: Flow quick actions are the most powerful for complex guided tasks without full-page navigation. Update actions are underused but eliminate the need to enter edit mode for single-field updates."),
                        StudyTopic(id: "s13_given_a_scenario_describe_declarative_fe_4", number: 4, question: "Using default field values to reduce manual data entry in Salesforce forms.", answer: "Default field values pre-populate a field with a specified value when a new record is created. They can be static (always default to 'New') or formula-based (default to today's date, the current user's name, or a value derived from related record data). From a UX standpoint, defaults reduce the number of fields users must manually fill in, decreasing entry time and error rates. Best practice: set defaults for fields with a high-probability correct value (e.g., default Record Type, Status, or Owner). Avoid defaults that are incorrect often enough to cause users to reflexively override them without checking."),
                        StudyTopic(id: "s13_given_a_scenario_describe_declarative_fe_5", number: 5, question: "Using formula fields to auto-populate fields and reduce manual data entry.", answer: "Formula fields calculate their value automatically from other fields, records, or functions and are read-only to users. Examples: a 'Days to Close' formula field on an Opportunity that calculates (Close Date - Today()); a 'Full Name' formula on a Contact that concatenates First Name and Last Name. From a UX standpoint, formula fields eliminate manual calculation tasks and ensure data consistency. They surface derived insights directly on the record without requiring a report. The trade-off: formula fields cannot be edited, so use them only when the calculated value should never be manually overridden."),
                        StudyTopic(id: "s13_given_a_scenario_describe_declarative_fe_6", number: 6, question: "Using dependent picklists to guide user choices and enforce valid field combinations.", answer: "A dependent picklist filters the available values in a child (dependent) picklist based on the selection in a parent (controlling) picklist. Example: selecting 'Hardware' as Product Category limits the Product Sub-Category picklist to only hardware-related options. UX benefit: users see only valid options, reducing errors from invalid combinations and simplifying decision-making. This is a form of progressive disclosure applied to data entry: you reveal only the choices that are relevant given the previous selection, reducing cognitive load in multi-field forms."),
                        StudyTopic(id: "s13_given_a_scenario_describe_declarative_fe_7", number: 7, question: "Applying validation rules to enforce data quality at the point of entry and evaluating their UX cost (friction) vs. benefit (data integrity).", answer: "Validation rules evaluate field values on save and block the save if the rule condition is true, displaying an error message. They enforce data integrity (e.g., Close Date cannot be in the past for Open Opportunities). UX cost: every validation rule adds friction to the save action. Poorly written validations block legitimate saves, frustrate users, and erode trust. UX benefit: bad data in = bad data out; validations prevent downstream reporting and process failures. Best practice: write clear, actionable error messages that tell the user exactly what to fix; avoid over-validating fields that are legitimately optional."),
                        StudyTopic(id: "s13_given_a_scenario_describe_declarative_fe_8", number: 8, question: "Selecting Screen Flows over Guided Action Lists vs. standard page layouts when a user must follow a prescribed multi-step data-entry process.", answer: "Standard page layout: user sees all fields at once and can enter data in any order. No enforcement of sequence. Appropriate for experienced users with non-linear tasks. Screen Flow: guides the user through a prescribed sequence of screens, showing only the relevant fields at each step. Enforces order and branching logic. Appropriate when steps must be completed in a specific order or when the next step depends on the previous answer. Guided Action List: a checklist of tasks that can be completed in any order and across multiple sessions. Appropriate for tasks that are non-linear and spread over time. Choose Screen Flow for sequential, session-based data entry with branching."),
                        StudyTopic(id: "s13_given_a_scenario_describe_declarative_fe_9", number: 9, question: "Determining when Flow's Screen component conditional visibility is preferable to building separate screens for branching logic.", answer: "Conditional visibility on a Screen component shows or hides individual fields/sections within a single screen based on the user's inputs on that screen. Use it when: the branching is minor (showing an extra field or section based on a previous answer) and does not change the overall form structure. Build separate Flow screens when: the branching significantly changes the content or structure of what the user sees (different sets of questions for different user paths). Using conditional visibility for major branching creates a confusing single screen; separate screens keep each step clean and focused."),
                        StudyTopic(id: "s13_given_a_scenario_describe_declarative_fe_10", number: 10, question: "Identifying when a Guided Action List (a flow-based checklist component) is preferable to a sequential Screen Flow for tasks that users complete non-linearly or across multiple sessions.", answer: "A Guided Action List displays a set of tasks (each powered by a Flow) as a checklist on a record page. Users can complete tasks in any order and return to incomplete tasks across sessions; progress is saved. Use it when: the onboarding or process tasks are independent of each other (no strict sequence required), users need to complete them over days or weeks (e.g., a new hire onboarding checklist), or users may be interrupted and need to resume. A sequential Screen Flow is a one-session experience that assumes the user will complete all steps in one sitting."),
                        StudyTopic(id: "s13_given_a_scenario_describe_declarative_fe_11", number: 11, question: "Using Process Automation (Flow-triggered) to auto-populate fields or send alerts, reducing the number of manual steps a user must take.", answer: "Flow-triggered automations (Record-Triggered Flows) run automatically when a record is created, updated, or deleted, without any user action. Examples: when an Opportunity Stage changes to 'Closed Won,' auto-populate the Actual Close Date field; send a Chatter notification to the Account Owner. UX benefit: automation removes repetitive, predictable tasks from the user's workflow, reducing manual steps and data entry errors. From a design standpoint, automations should be transparent to users (ideally communicated via in-app guidance or release notes) so they understand why fields auto-populate."),
                        StudyTopic(id: "s13_given_a_scenario_describe_declarative_fe_12", number: 12, question: "Evaluating the use of Macros in Service Cloud to enable agents to execute repetitive multi-step tasks with a single click.", answer: "Macros are pre-recorded sequences of actions (e.g., update a field, send an email, change status) that an agent can trigger with a single click from a Case or other Service Cloud record. They are designed for high-volume, repetitive tasks like responding to a common inquiry type. UX benefit: macros dramatically reduce the number of actions an agent must perform for routine tasks, freeing cognitive bandwidth for complex cases. Design consideration: macros should be named clearly so agents know exactly what each macro will do before triggering it, and should be reviewed periodically to ensure accuracy.")
                    ]
                )
            ]
        ),

        // Section 14: Given a scenario, determine which global Salesforce configur (6 topics)
        StudySection(
            id: "s14_given_a_scenario_determine_which_global_",
            title: "Given a scenario, determine which global Salesforce configuration to use for optimized user flow.",
            color: Color(red: 0.80, green: 0.40, blue: 0.20),
            lightColor: Color(red: 1.00, green: 0.94, blue: 0.88),
            icon: "chart.bar.xaxis.ascending",
            objectives: [
                StudyObjective(
                    id: "s14_given_a_scenario_determine_which_global__obj",
                    title: "Given a scenario, determine which global Salesforce configuration to use for optimized user flow.",
                    topics: [
                        StudyTopic(id: "s14_given_a_scenario_determine_which_global__1", number: 1, question: "Choosing the correct Lightning App configuration (navigation items, utility bar, app branding) to align with a user persona's primary workflow.", answer: "A Lightning App defines a tailored workspace: which objects appear in the navigation bar, which utility bar tools are available, and which branding (logo, color) is applied. For a sales rep persona: navigation should include Accounts, Contacts, Opportunities, and Reports; utility bar might include Notes and Recent Items. For a service agent persona: navigation includes Cases, Contacts, and Knowledge; utility bar includes Open CTI (phone), Macros, and Flow Launcher. The app should contain only what that persona needs, eliminating navigation noise from irrelevant objects."),
                        StudyTopic(id: "s14_given_a_scenario_determine_which_global__2", number: 2, question: "Using App Manager to assign custom apps to profiles and permission sets and the UX implications of app assignment on user experience.", answer: "In Setup > App Manager, admins create and manage Lightning apps and assign them to user profiles. When a user logs in, they see only the apps assigned to their profile in the App Launcher. UX implication: assigning the correct app to each profile ensures users land in their tailored workspace by default. If a user has multiple apps assigned, they must select the correct one from the App Launcher, which adds a step. Best practice: assign one primary app per persona profile and make it the default, reducing the decision load at login."),
                        StudyTopic(id: "s14_given_a_scenario_determine_which_global__3", number: 3, question: "Deciding when split view vs. standard navigation vs. console navigation in Lightning Apps is most appropriate for a described user workflow.", answer: "Standard navigation: one record open at a time; navigating to a new record closes the previous page. Best for users who work on one record at a time (e.g., a sales rep doing deep work on a single opportunity). Console navigation: multiple records open simultaneously as subtabs within a primary tab; records persist as tabs without losing context. Best for high-volume users who jump between many records (service agents). Split view: a side panel shows a list view or queue while the main area shows the selected record. Best for users who work a queue sequentially (e.g., an agent processing a case queue)."),
                        StudyTopic(id: "s14_given_a_scenario_determine_which_global__4", number: 4, question: "Identifying when to use the Salesforce Console app navigation model (multi-tab, split view, pinned regions) for high-volume users such as service agents who need to manage multiple records simultaneously.", answer: "The Service Console uses Console navigation to allow agents to keep multiple case records open simultaneously as subtabs, with the Cases list view pinned in split view on the left. Agents can switch between cases without losing their place. Pinned regions (fixed panels) keep tools like the utility bar, Open CTI phone, and knowledge sidebar always visible regardless of which record is open. This configuration is specifically designed for agents who handle 20-50+ cases per day and must context-switch frequently without losing information."),
                        StudyTopic(id: "s14_given_a_scenario_determine_which_global__5", number: 5, question: "Configuring the utility bar (open CTI, notes, recent items, flow launcher) to surface frequently used tools without disrupting the main workspace.", answer: "The utility bar is a persistent toolbar at the bottom of a Lightning App. Clicking a utility item opens a small panel above it without navigating away from the current page. Available utilities include: Open CTI (softphone integration), Notes (quickly capture notes), History (recent items), Flow (launch a quick flow), Macros, and custom utilities. Configure only the utilities the persona uses daily; every extra utility adds visual noise. UX best practice: the utility bar should be the 'right-hand drawer' of quick-access tools that would otherwise require full navigation to reach."),
                        StudyTopic(id: "s14_given_a_scenario_determine_which_global__6", number: 6, question: "Evaluating the role of global search and Search Layouts in helping users find records efficiently.", answer: "Global search (the search bar at the top of every Salesforce page) allows users to search across all objects. Search Layouts define which fields appear as columns in search results for each object type. UX implication: if a user searches for 'Acme' and the Account search results show only the Account Name, they cannot distinguish between 'Acme Corp - East' and 'Acme Corp - West' without clicking into each. Adding City or Account Owner to the Search Layout for Accounts gives users the context they need to identify the correct record from the results page, reducing unnecessary record openings.")
                    ]
                )
            ]
        ),

        // Section 15: Given a scenario, determine options for users to access onbo (5 topics)
        StudySection(
            id: "s15_given_a_scenario_determine_options_for_u",
            title: "Given a scenario, determine options for users to access onboarding, support, and learning.",
            color: Color(red: 0.25, green: 0.55, blue: 0.70),
            lightColor: Color(red: 0.88, green: 0.95, blue: 0.98),
            icon: "globe",
            objectives: [
                StudyObjective(
                    id: "s15_given_a_scenario_determine_options_for_u_obj",
                    title: "Given a scenario, determine options for users to access onboarding, support, and learning.",
                    topics: [
                        StudyTopic(id: "s15_given_a_scenario_determine_options_for_u_1", number: 1, question: "Selecting the appropriate in-app guidance mechanism (Prompts, Walkthroughs, or Help & Training) for a specific onboarding or adoption scenario.", answer: "Prompts (In-App Guidance): single-step pop-ups or banners that appear in context to highlight a feature or share information. Best for announcing a new feature or a one-time tip. Walkthroughs: multi-step guided tours that walk users through a sequence of UI elements with spotlights and instructions. Best for onboarding new users to a complex workflow. Help & Training: the Salesforce Help Menu (top-right ?) which can be customized with links to internal documentation, Trailhead modules, or support resources. Best as a persistent self-service resource. Match the mechanism to the complexity of the learning task and the one-time vs. ongoing nature of the need."),
                        StudyTopic(id: "s15_given_a_scenario_determine_options_for_u_2", number: 2, question: "Distinguishing between floating prompts, docked prompts, and targeted prompts in In-App Guidance and when each is appropriate.", answer: "Floating prompts: appear as a modal or banner in the center of the page, not anchored to a UI element. Best for general announcements or messages not tied to a specific UI component. Docked prompts: appear as a small panel docked to the bottom corner of the screen, persistent without blocking the workspace. Best for ongoing tips or step-by-step instructions the user may need while completing a task. Targeted prompts: anchored to a specific UI element with a pointer (like a tooltip spotlight). Best for calling attention to a specific button, field, or feature for the first time."),
                        StudyTopic(id: "s15_given_a_scenario_determine_options_for_u_3", number: 3, question: "Determining when a multi-step Walkthrough (In-App Guidance) is preferable to a single targeted prompt for introducing a new feature or process change.", answer: "A single targeted prompt is appropriate when: the new feature is a single UI element the user just needs to notice (e.g., a new button). A multi-step Walkthrough is appropriate when: the new feature requires the user to understand a sequence of steps or navigate to multiple parts of the UI to use it effectively (e.g., a new case escalation process that spans the record page, a new quick action, and a related list). Walkthroughs are more effort to build but provide a guided experience that reduces support tickets for complex process changes."),
                        StudyTopic(id: "s15_given_a_scenario_determine_options_for_u_4", number: 4, question: "Configuring custom help menu items and Salesforce Help & Training links to surface role-specific learning resources.", answer: "In Setup > Help Menu, admins can add custom items to the Help panel (the '?' icon in the header). These can link to internal process documentation, video tutorials, support ticket submission forms, or external resources. Items can be configured to appear only for users with specific profiles, allowing the Admin profile to see technical documentation while the End User profile sees simplified how-to guides. This transforms the generic Salesforce help menu into a role-specific, curated learning portal embedded directly in the workflow."),
                        StudyTopic(id: "s15_given_a_scenario_determine_options_for_u_5", number: 5, question: "Evaluating when Trailhead or myTrailhead (Enablement) is an appropriate learning delivery mechanism vs. in-app walkthroughs for Salesforce feature adoption.", answer: "Trailhead/myTrailhead is appropriate when: learning requires conceptual understanding before hands-on use (e.g., understanding what a case is before learning to create one), the content is long-form and better consumed outside the live application, or you need to track completion and award credentials. In-app Walkthroughs are appropriate when: the user needs to learn by doing in the actual system, the learning is triggered by a specific moment (first login, new feature release), or the task is simple enough to learn in 2-5 guided steps. In practice, pair both: Trailhead for foundational knowledge, Walkthroughs for just-in-time contextual guidance.")
                    ]
                )
            ]
        ),

        // Section 16: Given a scenario, describe how to apply branding to a soluti (4 topics)
        StudySection(
            id: "s16_given_a_scenario_describe_how_to_apply_b",
            title: "Given a scenario, describe how to apply branding to a solution.",
            color: Color(red: 0.70, green: 0.30, blue: 0.40),
            lightColor: Color(red: 0.98, green: 0.90, blue: 0.92),
            icon: "person.2.fill",
            objectives: [
                StudyObjective(
                    id: "s16_given_a_scenario_describe_how_to_apply_b_obj",
                    title: "Given a scenario, describe how to apply branding to a solution.",
                    topics: [
                        StudyTopic(id: "s16_given_a_scenario_describe_how_to_apply_b_1", number: 1, question: "Applying custom themes in Lightning Experience (logo, colors, default branding images) to align the internal org with corporate brand standards.", answer: "In Setup > Themes and Branding, admins can configure a custom theme: upload a logo, set the brand color (applied to the header and navigation bar), set default background images for the Salesforce home page, and choose a page background color. This declarative theming is limited but sufficient for basic brand alignment. It does not require code. The result is a recognizable internal org that reflects the company's visual identity, which improves user perception of the platform as a professional, integrated tool rather than a generic out-of-the-box system."),
                        StudyTopic(id: "s16_given_a_scenario_describe_how_to_apply_b_2", number: 2, question: "Configuring Experience Cloud site branding (header, footer, color palette, fonts) using the Experience Builder branding panel.", answer: "Experience Builder's Branding panel (accessible via the paint brush icon in the sidebar) allows designers to set: primary and secondary colors (applied to buttons, links, headers), background colors, font family (from a predefined list), and text colors. The header and footer components have their own style configuration for logo, background color, and navigation link colors. These settings generate CSS custom properties applied site-wide, ensuring visual consistency without writing code. For advanced customization (e.g., custom fonts not in the predefined list), CSS resource files can be uploaded."),
                        StudyTopic(id: "s16_given_a_scenario_describe_how_to_apply_b_3", number: 3, question: "Identifying the constraints of declarative branding (no custom CSS allowed in some contexts) and when to escalate to a developer for custom SLDS token overrides.", answer: "Declarative branding in Lightning Experience is intentionally limited: admins can set a brand color and logo, but cannot change font families, component-level colors, or advanced spacing. Some Experience Cloud templates also restrict CSS injection. When a brand requirement cannot be met declaratively (e.g., a specific Pantone color for button hover states, a custom font, or a uniquely branded component), escalate to a developer to apply SLDS token overrides or scoped CSS within custom Lightning components. The escalation point is when the brand requirement exceeds what the Setup UI can deliver."),
                        StudyTopic(id: "s16_given_a_scenario_describe_how_to_apply_b_4", number: 4, question: "Determining the UX impact of applying a dark vs. light background theme in a Salesforce console app used in low-light or high-volume environments.", answer: "A dark background theme (dark mode) reduces screen brightness and eye strain in low-light environments (e.g., a call center with dim lighting). It can also reduce blue light exposure during extended screen use. However, dark themes can reduce readability for small text and require careful attention to contrast ratios (WCAG still applies: text must meet 4.5:1 contrast on the dark background). In high-volume environments where agents stare at screens for 8+ hours, a dark theme is often preferred by users. Consider user preference (allow toggling) and validate all text contrast ratios on the dark background before deployment.")
                    ]
                )
            ]
        ),

        // Section 17: Given a scenario, plan methods for validating and testing a  (7 topics)
        StudySection(
            id: "s17_given_a_scenario_plan_methods_for_valida",
            title: "Given a scenario, plan methods for validating and testing a design with the end user.",
            color: Color(red: 0.40, green: 0.60, blue: 0.30),
            lightColor: Color(red: 0.92, green: 0.96, blue: 0.90),
            icon: "leaf.fill",
            objectives: [
                StudyObjective(
                    id: "s17_given_a_scenario_plan_methods_for_valida_obj",
                    title: "Given a scenario, plan methods for validating and testing a design with the end user.",
                    topics: [
                        StudyTopic(id: "s17_given_a_scenario_plan_methods_for_valida_1", number: 1, question: "Designing task scenarios for a usability test that are realistic, non-leading, and appropriately scoped to the design elements being evaluated.", answer: "A task scenario describes a situation that prompts the participant to interact with the design, without telling them how to do it. Good task: 'You just got off a call with a customer asking about their open order. Find out the current status of that order.' Bad task: 'Click on the Orders tab and then click the most recent order.' Realistic: grounded in an actual user goal. Non-leading: does not reveal the solution path. Appropriately scoped: tests specific components without being so broad that the session runs too long. Write 3-7 tasks per session focused on the highest-risk design decisions."),
                        StudyTopic(id: "s17_given_a_scenario_plan_methods_for_valida_2", number: 2, question: "Defining recruiting screener criteria to ensure usability test participants represent the target user population and are not biased by familiarity with the product.", answer: "A recruiting screener is a questionnaire that qualifies participants before a usability test. Criteria should match the target persona's key attributes: role/job title, industry, relevant experience level, technology comfort, and Salesforce familiarity (either filter for familiarity or specifically exclude it depending on the test goal). Exclude: current product team members, UX professionals (they analyze rather than use naturally), and participants who have been in a previous study of the same product. The screener ensures test results reflect real target user behavior, not expert or biased behavior."),
                        StudyTopic(id: "s17_given_a_scenario_plan_methods_for_valida_3", number: 3, question: "Determining the appropriate number of participants for a usability test session given the goal of finding major usability issues vs. reaching statistical significance.", answer: "Nielsen's research shows 5 participants in a qualitative usability test reveal approximately 85% of major usability issues. This is sufficient when the goal is to identify and fix problems before launch. Statistical significance (for quantitative metrics like task success rate or SUS scores) requires much larger samples: typically 20-100+ participants depending on the desired confidence level. For iterative, formative testing: use 5 participants per round. For summative benchmarking: use 20+ participants. The exam typically focuses on the 5-participant rule for qualitative usability testing."),
                        StudyTopic(id: "s17_given_a_scenario_plan_methods_for_valida_4", number: 4, question: "Selecting between moderated vs. unmoderated usability testing given constraints on user availability, facilitator skill, and research depth required.", answer: "Moderated testing: a facilitator guides the session in real time, asking follow-up questions, probing on unexpected behaviors, and adapting the script. Requires scheduling, a skilled facilitator, and user availability. Best when: deep qualitative insight is needed, the design is complex, or the tasks require guidance. Unmoderated testing: participants complete tasks on their own using a tool (e.g., UserTesting.com, Maze). Faster, cheaper, scalable, no scheduling. Best when: tasks are straightforward enough to complete without a facilitator, a larger sample is needed, or user availability is limited. Trade-off: less depth and no ability to probe unexpected behaviors."),
                        StudyTopic(id: "s17_given_a_scenario_plan_methods_for_valida_5", number: 5, question: "Choosing between remote and in-person usability testing methods given geographic distribution of users and required observation fidelity.", answer: "In-person testing: researcher observes body language, facial expressions, and environmental context in addition to screen interactions. Best for understanding emotional responses and context-dependent behaviors. Requires co-location and travel logistics. Remote testing: conducted via video conferencing (moderated) or online tools (unmoderated). Allows access to geographically distributed user populations and is more cost-effective. Best when: users are spread across regions, travel budget is limited, or the study requires a large sample. Remote testing has lower observation fidelity (no body language, potential for technical issues) but broader access."),
                        StudyTopic(id: "s17_given_a_scenario_plan_methods_for_valida_6", number: 6, question: "Selecting guerrilla (hallway) testing as an appropriate low-cost validation method for early-stage designs when formal participant recruitment is not feasible.", answer: "Guerrilla testing (also called hallway testing) involves approaching people in a public space (coffee shop, office hallway) and asking them to quickly test a design for 10-15 minutes in exchange for a small incentive. It is extremely fast and cheap. It is appropriate when: the design is early-stage and major structural issues are the target (not nuanced behavioral patterns), formal recruitment is not feasible due to time or budget, and the design is generic enough that almost any user can provide relevant feedback. It is NOT appropriate when the target persona is highly specialized (e.g., a cardiac surgeon) or when precise behavioral data is needed."),
                        StudyTopic(id: "s17_given_a_scenario_plan_methods_for_valida_7", number: 7, question: "Planning a first-click test or five-second test to validate whether a proposed navigation structure or landing page communicates its purpose effectively.", answer: "First-click test: shows participants a static design and asks them to click where they would go to complete a specific task. It validates navigation and IA decisions without requiring a fully interactive prototype. High first-click accuracy (70%+ on the correct target) predicts successful task completion. Five-second test: shows participants a design for 5 seconds, then asks what they remember and what the page is for. It validates whether the primary message, purpose, and visual hierarchy are immediately clear. Use these lightweight tests early in the design process to validate structural and communication decisions before investing in a full prototype.")
                    ]
                )
            ]
        ),

        // Section 18: Describe testing techniques needed for optimal user experien (9 topics)
        StudySection(
            id: "s18_describe_testing_techniques_needed_for_o",
            title: "Describe testing techniques needed for optimal user experiences.",
            color: Color(red: 0.50, green: 0.30, blue: 0.60),
            lightColor: Color(red: 0.94, green: 0.90, blue: 0.96),
            icon: "cpu.fill",
            objectives: [
                StudyObjective(
                    id: "s18_describe_testing_techniques_needed_for_o_obj",
                    title: "Describe testing techniques needed for optimal user experiences.",
                    topics: [
                        StudyTopic(id: "s18_describe_testing_techniques_needed_for_o_1", number: 1, question: "Distinguishing between formative testing (used to improve a design during development) and summative testing (used to evaluate a completed design against benchmarks).", answer: "Formative testing occurs during the design and development process. The goal is to find problems and improve the design iteratively. It is diagnostic. Small sample sizes (5 participants) and qualitative methods are typical. Summative testing occurs after a design is complete. The goal is to measure performance against defined benchmarks (e.g., task completion rate, time on task, error rate, SUS score). It is evaluative. Larger samples and quantitative metrics are used. Think of formative as 'cooking and tasting to adjust the recipe' and summative as 'judging the final dish against a standard.'"),
                        StudyTopic(id: "s18_describe_testing_techniques_needed_for_o_2", number: 2, question: "Defining the role of UAT (User Acceptance Testing) in a Salesforce implementation and how it differs from UX usability testing.", answer: "UAT (User Acceptance Testing) verifies that a Salesforce implementation meets the agreed-upon business requirements. Business stakeholders and power users test specific scenarios to confirm the system behaves correctly (e.g., 'Does the Opportunity stage update trigger the correct email notification?'). It is pass/fail against requirements. UX usability testing evaluates whether real users can effectively and efficiently accomplish their tasks using the interface. It is observational and focused on user behavior and experience, not requirements compliance. UAT happens late in a project; usability testing should happen much earlier, during design and prototype phases."),
                        StudyTopic(id: "s18_describe_testing_techniques_needed_for_o_3", number: 3, question: "Think-aloud protocol: purpose and output in usability testing.", answer: "In a think-aloud usability test, participants verbalize their thoughts, expectations, confusions, and decisions as they complete tasks. Purpose: surfaces the participant's mental model and reveals exactly where and why they encounter confusion or make errors, rather than just observing that they fail. Output: qualitative insights tied to specific UI moments (e.g., 'I expected this button to be here, not there') that provide actionable redesign direction. The facilitator's role is to encourage verbalization without steering the participant. Limitation: some users find it unnatural, and verbalization may slow task completion."),
                        StudyTopic(id: "s18_describe_testing_techniques_needed_for_o_4", number: 4, question: "Co-discovery: purpose and output in usability testing.", answer: "Co-discovery (also called pair testing) pairs two participants who complete tasks together and naturally talk to each other about the interface. Purpose: participants are more comfortable talking when addressing another person rather than a researcher, generating richer verbal data naturally without the artificiality of the think-aloud protocol. Output: conversations between participants reveal shared mental models, collaborative problem-solving, and moments of mutual confusion. Limitation: one participant may dominate, and the pair dynamic does not replicate individual use. Best used when natural verbalization is important and the task is collaborative in nature."),
                        StudyTopic(id: "s18_describe_testing_techniques_needed_for_o_5", number: 5, question: "Retrospective probing and concurrent probing: purpose and output in usability testing.", answer: "Concurrent probing: the facilitator asks questions during the task session, immediately after observing a specific behavior or moment of confusion. Best for clarifying specific moments in real time. Risk: interrupts the natural flow of task completion. Retrospective probing: the facilitator asks questions after the task is complete, often reviewing a screen recording with the participant. Best when interrupting would significantly bias task behavior (e.g., timed tasks). Risk: participants may not accurately recall their reasoning after the fact. Use concurrent probing for qualitative depth; use retrospective probing when task naturalism is paramount."),
                        StudyTopic(id: "s18_describe_testing_techniques_needed_for_o_6", number: 6, question: "Applying a System Usability Scale (SUS) questionnaire to quantify perceived usability after a usability test session and interpreting the score.", answer: "The SUS is a standardized 10-question Likert scale questionnaire administered after a usability test session. Questions alternate between positive and negative statements about the system's usability. Scores are calculated on a 0-100 scale. Score interpretation: above 80 = excellent (Grade A); 68-80 = good (Grade B/C); 51-68 = OK (Grade D); below 51 = poor (Grade F). The SUS provides a single quantitative benchmark that can be compared across releases or competing products, making it valuable for summative evaluation. It does not diagnose specific problems, so combine it with qualitative findings."),
                        StudyTopic(id: "s18_describe_testing_techniques_needed_for_o_7", number: 7, question: "Structuring a usability test findings report: how to communicate severity ratings, patterns observed, and design recommendations to stakeholders who did not observe the sessions.", answer: "A findings report should include: executive summary (top 3-5 findings for stakeholders who read only the summary), methodology section (who was tested, how many participants, how the test was conducted), findings organized by severity (critical > serious > minor > cosmetic), each finding supported by direct quotes, observed behaviors, and frequency, and actionable recommendations tied to each finding. Severity ratings help stakeholders prioritize: Critical (prevents task completion), Serious (causes significant difficulty), Minor (causes slight confusion), Cosmetic (aesthetic issue with no task impact)."),
                        StudyTopic(id: "s18_describe_testing_techniques_needed_for_o_8", number: 8, question: "Using screen readers and keyboard navigation testing to validate WCAG operability compliance of a Salesforce UI.", answer: "Screen reader testing uses assistive technology (NVDA, JAWS, VoiceOver) to navigate a Salesforce page and verify that all interactive elements are announced correctly and in a logical order, that custom LWC components have proper ARIA labels, and that dynamic content updates are announced. Keyboard navigation testing verifies that all functionality is reachable and operable using only the keyboard (Tab, Shift+Tab, Enter, Space, Arrow keys) without a mouse, and that there are no keyboard traps. These tests validate the Operable (and partially Robust) POUR principle requirements."),
                        StudyTopic(id: "s18_describe_testing_techniques_needed_for_o_9", number: 9, question: "Using color contrast checkers to validate WCAG perceivability compliance of a Salesforce UI.", answer: "Color contrast checkers (WebAIM Contrast Checker, browser DevTools, Figma accessibility plugins) calculate the contrast ratio between a text color and its background color. The calculated ratio is compared against WCAG thresholds: 4.5:1 for normal text, 3:1 for large text and UI components. Run contrast checks on all text, including placeholder text, field labels, help text, error messages, and icon labels. Ensure that interactive UI elements (buttons, input borders, focus indicators) also meet the 3:1 ratio. This directly validates the Perceivable principle.")
                    ]
                )
            ]
        ),

        // Section 19: Given a scenario, evaluate and manage design changes. (5 topics)
        StudySection(
            id: "s19_given_a_scenario_evaluate_and_manage_des",
            title: "Given a scenario, evaluate and manage design changes.",
            color: Color(red: 0.60, green: 0.50, blue: 0.20),
            lightColor: Color(red: 0.98, green: 0.96, blue: 0.88),
            icon: "lightbulb.fill",
            objectives: [
                StudyObjective(
                    id: "s19_given_a_scenario_evaluate_and_manage_des_obj",
                    title: "Given a scenario, evaluate and manage design changes.",
                    topics: [
                        StudyTopic(id: "s19_given_a_scenario_evaluate_and_manage_des_1", number: 1, question: "The four severity levels for usability findings: critical, serious, minor, and cosmetic.", answer: "Critical: the user cannot complete the task. This is a showstopper. Must be fixed before launch. Example: a required field has no visible label, so users cannot complete a form. Serious: the user completes the task but with significant difficulty, errors, or workarounds. Should be fixed before launch if possible. Example: a key button is hidden in a dropdown that users consistently overlook. Minor: causes slight confusion or a small delay but does not prevent task completion. Fix post-launch if time permits. Example: an error message is slightly unclear but users eventually understand it. Cosmetic: aesthetic issues with no task impact. Fix if time and budget allow. Example: inconsistent icon sizing."),
                        StudyTopic(id: "s19_given_a_scenario_evaluate_and_manage_des_2", number: 2, question: "Determining which usability findings to address before launch vs. post-launch based on severity and resource constraints.", answer: "All Critical findings must be resolved before launch: they block users from completing core tasks, making the product unusable for its intended purpose. Serious findings should be addressed pre-launch if the development timeline allows; otherwise, a documented mitigation plan is required. Minor and Cosmetic findings can be deferred to a post-launch backlog without significant user impact. Resource constraints (time, budget, developer capacity) are the primary reason for deferral decisions. Always document deferred findings with severity ratings and schedule them for the first post-launch sprint to prevent them from being forgotten."),
                        StudyTopic(id: "s19_given_a_scenario_evaluate_and_manage_des_3", number: 3, question: "Deciding when a design change discovered during testing requires a new round of prototype validation vs. can be implemented and validated in production.", answer: "Require a new prototype round when: the change is significant enough to alter user flow or introduce new interaction patterns (high risk of introducing new issues), the design team is uncertain about the correct solution, or the change is large enough to warrant validation before development cost is incurred. Implement and validate in production when: the change is small and low-risk (e.g., rewording an error message, increasing button size), the change directly addresses a clear finding with an obvious solution, and analytics or feedback tools can confirm improvement post-launch. Use the risk/effort matrix: high risk = prototype first; low risk = build and monitor."),
                        StudyTopic(id: "s19_given_a_scenario_evaluate_and_manage_des_4", number: 4, question: "Managing stakeholder pushback on user-validated design changes by presenting evidence from usability testing and framing changes as risk mitigation.", answer: "Stakeholders may resist design changes because they add scope, delay timelines, or challenge their original vision. Counter this by presenting: video clips or direct quotes from usability sessions showing users struggling, task completion rate data (e.g., '3 out of 5 users failed to find this button'), and the business risk of launching a design that causes user failure (support ticket volume, user abandonment, adoption failure). Frame changes as risk mitigation, not redesign: 'If we launch without fixing this, we predict X% of users will fail at this step, generating Y support tickets.' Evidence beats opinion."),
                        StudyTopic(id: "s19_given_a_scenario_evaluate_and_manage_des_5", number: 5, question: "Using analytics and feedback tools (Salesforce Feedback Management, in-app surveys) post-launch to identify usability regressions and guide iterative improvements.", answer: "Post-launch validation closes the design loop. Salesforce Feedback Management allows admins to create and deploy in-app surveys that appear after specific user actions or milestones (e.g., after completing a case, after first login). Use CSAT or NPS questions alongside open-text fields to capture user sentiment and specific pain points. Complement surveys with behavioral analytics (click paths, time on page, drop-off rates via tools like Salesforce Shield event monitoring or third-party analytics). Monitor for regressions after each release. A usability regression is a measurable decline in task success or user satisfaction that wasn't present before a change.")
                    ]
                )
            ]
        ),

        // Section 20: Describe SLDS and its purpose. (7 topics)
        StudySection(
            id: "s20_describe_slds_and_its_purpose",
            title: "Describe SLDS and its purpose.",
            color: Color(red: 0.35, green: 0.45, blue: 0.65),
            lightColor: Color(red: 0.90, green: 0.92, blue: 0.96),
            icon: "building.2.fill",
            objectives: [
                StudyObjective(
                    id: "s20_describe_slds_and_its_purpose_obj",
                    title: "Describe SLDS and its purpose.",
                    topics: [
                        StudyTopic(id: "s20_describe_slds_and_its_purpose_1", number: 1, question: "Explaining the core purpose of SLDS: providing a shared visual language and CSS framework that ensures consistency between custom components and native Lightning Experience.", answer: "The Salesforce Lightning Design System (SLDS) is an open-source CSS framework that defines the visual language of Lightning Experience: colors, typography, spacing, iconography, and component patterns. Its core purpose is to give developers a toolkit for building custom components that visually match native Salesforce components. Without SLDS, custom LWC or Aura components would look visually inconsistent with the rest of the Salesforce UI, degrading user experience. SLDS is the design contract between Salesforce's product design and the developer community."),
                        StudyTopic(id: "s20_describe_slds_and_its_purpose_2", number: 2, question: "Describing the relationship between SLDS and Lightning Web Components (LWC): LWC base components automatically apply SLDS styling; custom LWC components must manually apply SLDS.", answer: "Lightning Web Components (LWC) base components (lightning-button, lightning-card, lightning-input, lightning-datatable, etc.) are pre-built by Salesforce and automatically apply SLDS styling. Developers do not need to add SLDS classes to use them. When developers build custom LWC components from scratch (e.g., a custom card layout using plain HTML div elements), they must manually apply SLDS CSS classes, design tokens, and utility classes to achieve visual consistency with Lightning Experience. The rule: use LWC base components whenever available; apply SLDS manually only when base components cannot meet the requirement."),
                        StudyTopic(id: "s20_describe_slds_and_its_purpose_3", number: 3, question: "Identifying what SLDS does NOT provide: it is a CSS framework and visual specification, not a JavaScript component library, and does not replace LWC or Aura component logic.", answer: "SLDS provides: CSS classes, design tokens, utility classes, component blueprints (HTML markup patterns), and an icon library. SLDS does NOT provide: JavaScript logic, data binding, component reactivity, state management, or API calls. It is purely a visual framework. Developers must still use LWC or Aura for component behavior. An SLDS blueprint shows you how to mark up a modal dialog with correct CSS classes; LWC provides the JavaScript to open and close it. Confusing SLDS for a full component library (like React's Material UI) is a common misconception."),
                        StudyTopic(id: "s20_describe_slds_and_its_purpose_4", number: 4, question: "SLDS design tokens: purpose and when to use them in a Lightning component.", answer: "Design tokens are named variables that store visual design values: colors, spacing, font sizes, border radii, and more. Example: --slds-c-button-color-background-primary stores the primary button background color. When a developer applies this token rather than a hard-coded hex value (#005FB2), the component automatically updates if Salesforce changes the token value in a future release. Use design tokens in LWC CSS files to set colors, spacing, and typography rather than hard-coding values. This ensures the component stays visually aligned with Lightning Experience across releases."),
                        StudyTopic(id: "s20_describe_slds_and_its_purpose_5", number: 5, question: "Explaining SLDS design tokens and how they allow global visual changes (color, spacing, font) to propagate consistently across a custom Lightning component.", answer: "When an organization updates its Lightning theme color (via Setup > Themes and Branding), SLDS design tokens that reference brand color values automatically propagate the change to all components using those tokens. A custom LWC that uses the --slds-c-button-color-brand token for its primary action button will automatically reflect the updated brand color without any code changes. This is the power of tokens: they decouple visual values from component code, enabling global visual updates. Components that hard-code hex values break this propagation."),
                        StudyTopic(id: "s20_describe_slds_and_its_purpose_6", number: 6, question: "SLDS utility classes: purpose and when to use them in a Lightning component.", answer: "SLDS utility classes are single-purpose CSS classes that apply a specific visual or layout property. Examples: slds-m-top_small (adds a small top margin), slds-text-heading_small (applies small heading typography), slds-grid (applies a flexbox grid container), slds-col (defines a grid column), slds-hide (hides an element). Use utility classes in HTML templates to quickly apply spacing, text styles, layout, and alignment without writing custom CSS. They are the fastest way to apply SLDS-consistent styling and should be the first tool developers reach for before writing any custom CSS."),
                        StudyTopic(id: "s20_describe_slds_and_its_purpose_7", number: 7, question: "SLDS component blueprints: purpose and when to use them in a Lightning component.", answer: "SLDS component blueprints are reference HTML + CSS templates for every standard UI pattern in Lightning Experience: modals, cards, data tables, forms, badges, pills, page headers, and more. They show exactly which SLDS classes to apply to which HTML elements to replicate the native appearance of that component. Use blueprints when: no LWC base component exists for the required UI pattern, and you need to build the component from scratch in a way that visually matches Lightning Experience. Blueprints are the specification; developers implement them using LWC HTML and the provided SLDS classes.")
                    ]
                )
            ]
        ),

        // Section 21: Given a scenario, determine out-of-the-box design and config (5 topics)
        StudySection(
            id: "s21_given_a_scenario_determine_out_of_the_bo",
            title: "Given a scenario, determine out-of-the-box design and configuration consistent with the look and feel of Lightning Experience.",
            color: Color(red: 0.30, green: 0.50, blue: 0.80),
            lightColor: Color(red: 0.90, green: 0.94, blue: 1.00),
            icon: "doc.text.fill",
            objectives: [
                StudyObjective(
                    id: "s21_given_a_scenario_determine_out_of_the_bo_obj",
                    title: "Given a scenario, determine out-of-the-box design and configuration consistent with the look and feel of Lightning Experience.",
                    topics: [
                        StudyTopic(id: "s21_given_a_scenario_determine_out_of_the_bo_1", number: 1, question: "Evaluating when a standard LWC base component (lightning-button, lightning-card, lightning-datatable) already follows SLDS guidelines vs. when a custom implementation is required.", answer: "LWC base components are pre-built, maintained by Salesforce, and automatically SLDS-compliant. Use them whenever they meet the functional requirement. Evaluate custom implementation only when: the base component cannot be configured to meet the requirement, a unique interaction pattern is needed that no base component supports, or a specific accessibility feature is absent. Common base components: lightning-button (all button types), lightning-card (content containers), lightning-datatable (read-only or editable data tables), lightning-input (form fields), lightning-combobox (select menus). Default to base components; escalate to custom only when necessary."),
                        StudyTopic(id: "s21_given_a_scenario_determine_out_of_the_bo_2", number: 2, question: "Selecting the correct SLDS component blueprint (data table, card, modal, badge, pill) to match a described UI requirement without custom development.", answer: "SLDS blueprints map to common UI patterns: Data table: display structured tabular data with sortable columns and row actions. Card: contain a related set of information in a visually bordered unit with a header and body. Modal: overlay dialog for focused user actions (create, confirm, alert). Badge: small label indicating a status or category (e.g., 'New', 'Hot'). Pill: compact tag representing a selected item or filter that can be removed. Select the blueprint that most closely matches the described layout and interaction pattern. If the base LWC component for that pattern exists, use it; if not, implement the blueprint's HTML + SLDS classes."),
                        StudyTopic(id: "s21_given_a_scenario_determine_out_of_the_bo_3", number: 3, question: "Identifying which SLDS utility classes (spacing, alignment, text, grid) should be applied to achieve a described layout without writing custom CSS.", answer: "Spacing: slds-m-{direction}_{size} for margin, slds-p-{direction}_{size} for padding. Directions: top, bottom, left, right, horizontal, vertical, around. Sizes: xxx-small through xx-large. Alignment: slds-align_absolute-center, slds-float_left, slds-text-align_center. Text: slds-text-heading_{size}, slds-text-body_{size}, slds-text-color_weak. Grid: slds-grid (flex container), slds-col (flex column), slds-wrap (wrapping), slds-grid_pull-padded (remove gutters). Before writing any custom CSS for a layout task, search the SLDS documentation for a utility class that achieves it. Custom CSS should be a last resort."),
                        StudyTopic(id: "s21_given_a_scenario_determine_out_of_the_bo_4", number: 4, question: "Using SLDS icons (utility, action, standard, custom, doctype sprite categories) correctly in a custom component to maintain visual consistency with Lightning Experience.", answer: "SLDS icons are organized into sprite categories: Utility icons (generic UI symbols like 'search', 'settings', 'chevrondown'): used for UI actions and navigation. Action icons (colored circles with white symbols like 'new_task', 'email'): used in quick action menus. Standard icons (colored squares representing Salesforce standard objects like 'account', 'contact'): used in object navigation and record headers. Custom icons (for custom objects): follow the same pattern as standard icons. Doctype icons: represent file types. In LWC, use the lightning-icon base component with the correct icon-name format (category:icon-name) to render SLDS icons consistently."),
                        StudyTopic(id: "s21_given_a_scenario_determine_out_of_the_bo_5", number: 5, question: "Selecting SLDS data table variants (with row actions, with inline editing, read-only) and identifying the appropriate variant given a described user task.", answer: "Read-only data table: displays tabular data without editing capability. Use for dashboards, reporting views, or reference tables. Row actions data table: adds a dropdown action menu per row (e.g., Edit, Delete, View). Use when users need to perform contextual actions on individual records from the table. Inline editing data table: allows users to click a cell to edit its value directly in the table without opening a separate record page. Use for high-volume data entry tasks where editing efficiency is critical (e.g., updating multiple line items on an order). In LWC, use the lightning-datatable base component with the appropriate columns and editable configuration.")
                    ]
                )
            ]
        ),

        // Section 22: Given a scenario, utilize SLDS to create new and customized  (6 topics)
        StudySection(
            id: "s22_given_a_scenario_utilize_slds_to_create_",
            title: "Given a scenario, utilize SLDS to create new and customized component functionality.",
            color: Color(red: 0.20, green: 0.60, blue: 0.50),
            lightColor: Color(red: 0.88, green: 0.96, blue: 0.94),
            icon: "checkmark.shield.fill",
            objectives: [
                StudyObjective(
                    id: "s22_given_a_scenario_utilize_slds_to_create__obj",
                    title: "Given a scenario, utilize SLDS to create new and customized component functionality.",
                    topics: [
                        StudyTopic(id: "s22_given_a_scenario_utilize_slds_to_create__1", number: 1, question: "Identifying the trade-offs of styling a custom LWC with SLDS utility classes vs. writing scoped CSS in the component's .css file, and when each approach is appropriate.", answer: "SLDS utility classes: applied directly in HTML; fast, consistent with SLDS, no additional CSS file changes needed, and automatically updated with SLDS releases. Use when SLDS utility classes can achieve the required styling. Scoped CSS in .css file: allows custom styling specific to the component; necessary when utility classes cannot achieve the requirement. LWC CSS is automatically scoped (shadow DOM) so styles do not leak outside the component. Trade-off: custom CSS can break visual consistency if it overrides SLDS values without using tokens, and may not update automatically with Salesforce releases. Use utility classes first; write scoped CSS only for requirements beyond utility class capabilities."),
                        StudyTopic(id: "s22_given_a_scenario_utilize_slds_to_create__2", number: 2, question: "Applying SLDS design tokens to override default visual styles in a custom LWC without breaking Lightning Experience consistency.", answer: "To override a visual style in a custom LWC: use the corresponding SLDS design token as a CSS custom property in the component's .css file rather than hard-coding a value. Example: to set a button's background color to match the brand color, use: background-color: var(--slds-c-button-color-background-primary) rather than background-color: #005FB2. This ensures the component respects the org's theme settings and does not visually break when Salesforce updates the token value in a new release. Always reference SLDS token documentation to find the correct token for the property being styled."),
                        StudyTopic(id: "s22_given_a_scenario_utilize_slds_to_create__3", number: 3, question: "Using SLDS Blueprints as a reference specification to implement a custom component that visually matches native Lightning Experience elements when no base LWC is available.", answer: "When no base LWC component exists for a required UI pattern (e.g., a custom timeline, a custom progress indicator), the developer uses the SLDS Blueprint for that pattern as the implementation specification. The blueprint provides: the exact HTML structure (div nesting, element hierarchy), the SLDS CSS classes to apply to each element, and modifier classes for different states (is-active, is-expanded). The developer copies the blueprint HTML into the LWC template, applies the specified SLDS classes, and adds LWC JavaScript for behavior. This ensures the custom component is visually indistinguishable from a native Salesforce component."),
                        StudyTopic(id: "s22_given_a_scenario_utilize_slds_to_create__4", number: 4, question: "Selecting the correct SLDS state classes (is-active, is-open, is-selected, has-error) to reflect dynamic component states in a custom Lightning component.", answer: "SLDS state classes are applied conditionally via LWC's template binding to visually reflect the current state of a component. is-active: highlights the currently selected/active item (e.g., active navigation tab). is-open: indicates a dropdown, accordion, or popover is expanded. is-selected: marks a selected item in a list or tree. has-error: applies error styling to a form field or section. In LWC, bind these conditionally: class={computedClass} where computedClass is a getter that returns the appropriate SLDS classes based on component state. Using correct state classes ensures dynamic behavior is visually consistent with native Lightning components."),
                        StudyTopic(id: "s22_given_a_scenario_utilize_slds_to_create__5", number: 5, question: "Applying SLDS validation patterns (inline error messages, required field indicators, help text icons) to a custom form component to communicate input errors accessibly.", answer: "SLDS provides standardized HTML patterns for form validation: Required field indicator: add slds-required span with asterisk inside the label element. Inline error message: add an element with class slds-form-error or slds-has-error on the parent slds-form-element div, with the error text in a p.slds-form-error below the input. Help text icon: use the lightning-helptext base component for a question mark icon with a tooltip. Accessibility requirement: error messages must be programmatically associated with the input using aria-describedby so screen readers announce them when the field is focused. Apply the has-error state class to update field border and icon colors."),
                        StudyTopic(id: "s22_given_a_scenario_utilize_slds_to_create__6", number: 6, question: "Using SLDS loading spinner and skeleton screen patterns in a custom component to communicate system processing state and prevent users from perceiving the interface as broken.", answer: "Loading spinner: the SLDS spinner component (use lightning-spinner base component or apply slds-spinner SLDS classes) displays an animated circle to indicate the system is processing. Use for operations expected to complete in under 10 seconds. Skeleton screen: displays placeholder gray blocks in the shape of the expected content while data is loading (e.g., gray rectangles where text and images will appear). Skeleton screens are preferred over spinners for initial page loads because they reduce perceived wait time by showing the page structure immediately. Both patterns address Nielsen Heuristic #1 (Visibility of System Status) and prevent users from thinking the page has frozen.")
                    ]
                )
            ]
        )

    ]
}
